// Control UI response helpers own bounded browser body consumption.
import { consumeResponseBytes } from "@openclaw/normalization-core";

type ResponseTextLimitOptions = {
  maxBytes: number;
  tooLargeMessage: string;
  missingBodyMessage?: string;
};

function parseContentLength(headers: Headers): number | null {
  const raw = headers.get("content-length");
  if (!raw || !/^\d+$/u.test(raw)) {
    return null;
  }
  const parsed = Number(raw);
  return Number.isSafeInteger(parsed) ? parsed : Number.POSITIVE_INFINITY;
}

export async function readResponseTextWithLimit(
  response: Response,
  options: ResponseTextLimitOptions,
): Promise<string> {
  const contentLength = parseContentLength(response.headers);
  if (contentLength !== null && contentLength > options.maxBytes) {
    void response.body?.cancel().catch(() => undefined);
    throw new Error(options.tooLargeMessage);
  }
  if (!response.body) {
    if (options.missingBodyMessage) {
      throw new Error(options.missingBodyMessage);
    }
    return "";
  }

  const reader = response.body.getReader();
  const decoder = new TextDecoder();
  const chunks: string[] = [];
  try {
    await consumeResponseBytes({
      maxBytes: options.maxBytes,
      skipEmptyChunks: false,
      read: () => reader.read(),
      onChunk: (chunk) => {
        chunks.push(decoder.decode(chunk, { stream: true }));
      },
      onLimit: () => {
        void reader.cancel().catch(() => undefined);
        throw new Error(options.tooLargeMessage);
      },
    });
    const tail = decoder.decode();
    if (tail) {
      chunks.push(tail);
    }
  } finally {
    reader.releaseLock();
  }
  return chunks.join("");
}
